    31→            'image': { id: 'image', content: '🖼️ Image', style: 'background-color: #e1f5fe;' }
    32→        };
    33→
    34→        // Build timeline data from messages
    35→        function buildTimelineData() {
    36→            const timelineItems = [];
    37→            const timelineGroups = [];
    38→            const usedGroups = new Set();
    39→
    40→            // Clear existing mapping
    41→            timelineIdToElement.clear();
    42→
    43→            // Get all messages from the page
    44→            const messages = document.querySelectorAll('.message:not(.session-header)');
    45→
    46→            messages.forEach((messageEl, index) => {
    47→                // Extract message data
    48→                const messageType = Array.from(messageEl.classList).find(cls =>
    49→                    Object.keys(messageTypeGroups).includes(cls)
    50→                ) || 'system';
    51→
    52→                const timestampEl = messageEl.querySelector('.timestamp');
    53→                if (!timestampEl) return; // Skip if no timestamp
    54→                const timestamp = timestampEl.textContent.trim();
    55→
    56→                // Get message content preview
    57→                const contentEl = messageEl.querySelector('.content');
    58→                let content = '';
    59→                if (contentEl) {
    60→                    const textContent = contentEl.textContent || contentEl.innerText || '';
    61→                    content = textContent.length > 100 ? textContent.substring(0, 100) + '...' : textContent;
    62→                }
    63→
    64→                // For tool_use messages, try to extract the tool name
    65→                if (messageType === 'tool_use') {
    66→                    // Try to extract tool name from JSON content
    67→                    const nameMatch = content.match(/"name":\s*"([^"]+)"/);
    68→                    if (nameMatch) {
    69→                        const toolName = nameMatch[1];
    70→                        content = toolName + ': ' + content.replace(/"name":\s*"[^"]+",?\s*/, '');
    71→                    } else {
    72→                        // Fallback: try to extract from header if available
    73→                        const headerEl = messageEl.querySelector('.header span');
    74→                        if (headerEl) {
    75→                            const headerText = headerEl.textContent || '';
    76→                            const toolMatch = headerText.match(/🛠️\s*(.+) \(Id:.*/);
    77→                            if (toolMatch) {
    78→                                content = toolMatch[1].replace("Tool Use: ", "") + (content ? ': ' + content : '');
    79→                            }
    80→                        }
    81→                    }
    82→                }
    83→
    84→                // Add group if not already added
    85→                if (!usedGroups.has(messageType)) {
    86→                    timelineGroups.push(messageTypeGroups[messageType]);
    87→                    usedGroups.add(messageType);
    88→                }
    89→
    90→                // Store mapping for click handling
    91→                timelineIdToElement.set(index, messageEl);
    92→
    93→                // Strip content to make tooltip formatting more uniform
    94→                // TODO: this is very basic and TodoWrites have weird spacing so will need some more work
    95→                let title = contentEl.innerHTML.includes("<pre") ? contentEl.innerHTML : `<pre>${contentEl.innerHTML}</pre>`
    96→                if (title.includes("<details")) {
    97→                    title = title.replace(/(<summary>.*<\/summary>)/gs, '').replace(/<details class="collapsible-details">(.*?)<\/details>/gs, (m, p) => p)
    98→                }
    99→                title = title.replace(/<pre>[\s\r\n]+(.*?)[\s\r\n]+<\/pre>/gs, (m, p) => `<pre>${p}</pre>`)
   100→
   101→                // Create timeline item
   102→                timelineItems.push({
   103→                    id: index,
   104→                    content: content || messageTypeGroups[messageType].content,
   105→                    start: timestamp,
   106→                    group: messageType,
   107→                    tooltip: {
   108→                        // FIXME: This followMouse doesn't work for some reason and the tooltip box gets cut off for the bottom timeline boxes
   109→                        followMouse: true,
   110→                        overflowMethod: 'cap'
   111→                    },
   112→                    title,
   113→                    className: `timeline-item-${messageType}`
   114→                });
   115→            });
   116→
   117→            return { items: timelineItems, groups: timelineGroups };
   118→        }
   119→
   120→        // Filter timeline items based on current message filters
   121→        function applyFilters() {
   122→            if (!timeline || !items) return;
   123→
   124→            // Get active filter types
   125→            const filterToggles = document.querySelectorAll('.filter-toggle');
   126→            const activeTypes = [];
   127→            let hasActiveFilters = false;
   128→
   129→            filterToggles.forEach(toggle => {
   130→                if (toggle.classList.contains('active')) {
   131→                    activeTypes.push(toggle.dataset.type);
   132→                    hasActiveFilters = true;
   133→                }
   134→            });
   135→
   136→            // If no filters are active, show all items
   137→            if (!hasActiveFilters) {
   138→                timeline.setItems(items);
   139→                return;
   140→            }
   141→
   142→            // Filter items based on active types
   143→            const filteredItems = items.get().filter(item => {
   144→                return activeTypes.includes(item.group);
   145→            });
   146→
   147→            timeline.setItems(new vis.DataSet(filteredItems));
   148→        }
   149→
   150→        // Handle timeline item click - scroll to corresponding message
   151→        function onTimelineSelect(event) {
   152→            const selection = timeline.getSelection();
   153→            if (selection.length > 0) {
   154→                const itemId = selection[0];
   155→                const messageEl = timelineIdToElement.get(itemId);
   156→                if (messageEl) {
   157→                    // Calculate timeline height for proper scroll positioning
   158→                    const timelineContainer = document.getElementById('timeline-container');
   159→                    const timelineHeight = timelineContainer ? timelineContainer.offsetHeight : 0;
   160→
   161→                    // Scroll so message top aligns with timeline bottom
   162→                    const elementTop = messageEl.offsetTop;
   163→                    const scrollPosition = elementTop - timelineHeight - 10; // 10px padding
   164→
   165→                    window.scrollTo({
   166→                        top: Math.max(0, scrollPosition),
   167→                        behavior: 'smooth'
   168→                    });
   169→
   170→                    // Highlight the message briefly
   171→                    messageEl.style.backgroundColor = '#fff3cd';
   172→                    setTimeout(() => {
   173→                        messageEl.style.backgroundColor = '';
   174→                    }, 2000);
   175→                }
   176→            }
   177→        }
   178→
   179→        // Initialize timeline
   180→        function initTimeline() {
   181→            if (timeline) return; // Already initialized
   182→
   183→            console.log('Initializing vis-timeline...');
   184→
   185→            const container = document.getElementById('timeline-visualization');
   186→            if (!container) {
   187→                console.error('Timeline container not found');
   188→                return;
   189→            }
   190→
   191→            // Build timeline data
   192→            const timelineData = buildTimelineData();
   193→            if (timelineData.items.length === 0) {
   194→                console.warn('No timeline items found');
   195→                return;
   196→            }
   197→
   198→            // Create DataSets
   199→            items = new vis.DataSet(timelineData.items);
   200→            groups = new vis.DataSet(timelineData.groups);
   201→
   202→            // Timeline options
   203→            const options = {
   204→                height: '100%',
   205→                stack: true,
   206→                showCurrentTime: true,
   207→                zoomMin: 1000 * 1, // 1 second
   208→                zoomMax: 1000 * 60 * 60 * 24 * 30, // 30 days
   209→                orientation: 'top',
   210→                align: 'left',
   211→                margin: {
   212→                    item: 2,
   213→                    axis: 2
   214→                },
   215→                groupOrder: (a, b) => {
   216→                    const order = ['user', 'assistant', 'tool_use', 'tool_result', 'thinking', 'system', 'image'];
   217→                    return order.indexOf(a.id) - order.indexOf(b.id);
   218→                }
   219→            };
   220→
   221→            // Create timeline
   222→            timeline = new vis.Timeline(container, items, groups, options);
   223→
   224→            // Add event listeners
   225→            timeline.on('select', onTimelineSelect);
   226→
   227→            // Apply current filters
   228→            applyFilters();
   229→
   230→            console.log('Timeline initialized with', timelineData.items.length, 'items and', timelineData.groups.length, 'groups');
   231→        }
   232→
   233→        // Load vis-timeline library dynamically
   234→        function loadVisTimeline() {
   235→            return new Promise((resolve, reject) => {
   236→                if (window.vis && window.vis.Timeline) {
   237→                    resolve();
   238→                    return;
   239→                }
   240→
   241→                console.log('Loading vis-timeline from CDN...');
   242→
   243→                // Load CSS first
   244→                const link = document.createElement('link');
   245→                link.rel = 'stylesheet';
   246→                link.href = 'https://unpkg.com/vis-timeline/styles/vis-timeline-graph2d.min.css';
   247→                document.head.appendChild(link);
   248→
   249→                // Load JavaScript
   250→                const script = document.createElement('script');
   251→                script.src = 'https://unpkg.com/vis-timeline/standalone/umd/vis-timeline-graph2d.min.js';
   252→                script.onload = () => {
   253→                    console.log('vis-timeline loaded successfully');
   254→                    isTimelineLoaded = true;
   255→                    resolve();
   256→                };
   257→                script.onerror = () => {
   258→                    console.error('Failed to load vis-timeline');
   259→                    reject(new Error('Failed to load vis-timeline'));
   260→                };
   261→                document.head.appendChild(script);
   262→            });
   263→        }
   264→
   265→        // Toggle timeline visibility
   266→        function toggleTimeline() {
   267→            const container = document.getElementById('timeline-container');
   268→            const button = document.getElementById('toggleTimeline');
   269→
   270→            if (container.style.display === 'none') {
   271→                // Show timeline
   272→                button.classList.add('active');
   273→                button.title = 'Hide timeline';
   274→                button.textContent = '🗓️';
   275→
   276→                // Load vis-timeline if needed and show timeline
   277→                loadVisTimeline().then(() => {
   278→                    container.style.display = 'block';
   279→                    // Set default height if not already set
   280→                    if (!container.style.height) {
   281→                        container.style.height = '30vh';
   282→                    }
   283→                    // Wait for container to be visible, then initialize
   284→                    setTimeout(() => {
   285→                        initTimeline();
   286→                        initTimelineResize();
   287→                    }, 100);
   288→                }).catch(error => {
   289→                    console.error('Error loading timeline:', error);
   290→                    alert('Failed to load timeline. Please check your internet connection.');
   291→                    container.style.display = 'none';
   292→                    button.classList.remove('active');
   293→                    button.title = 'Show timeline';
   294→                    button.textContent = '📆';
   295→                });
   296→            } else {
   297→                // Hide timeline
   298→                container.style.display = 'none';
   299→                button.classList.remove('active');
   300→                button.title = 'Show timeline';
   301→                button.textContent = '📆';
   302→            }
   303→        }
   304→
   305→        // Update timeline position when filter bar is toggled
   306→        function updateTimelinePosition() {
   307→            const container = document.getElementById('timeline-container');
   308→            const filterToolbar = document.querySelector('.filter-toolbar');
   309→
   310→            if (container && filterToolbar) {
   311→                const filterHeight = filterToolbar.offsetHeight;
   312→                const computedStyle = getComputedStyle(filterToolbar);
   313→                const isFilterVisible = computedStyle.display !== 'none' &&
   314→                    computedStyle.visibility !== 'hidden' &&
   315→                    filterHeight > 0;
   316→
   317→                container.style.top = isFilterVisible ? `${filterHeight}px` : '0px';
   318→            }
   319→        }
   320→
   321→        // Initialize timeline resizing functionality
   322→        function initTimelineResize() {
   323→            const container = document.getElementById('timeline-container');
   324→            const resizeHandle = document.getElementById('timeline-resize-handle');
   325→
   326→            if (!container || !resizeHandle) return;
   327→
   328→            let startY = 0;
   329→            let startHeight = 0;
   330→
   331→            function handleMouseDown(e) {
   332→                isResizing = true;
   333→                startY = e.clientY;
   334→                startHeight = container.offsetHeight;
   335→
   336→                document.addEventListener('mousemove', handleMouseMove);
   337→                document.addEventListener('mouseup', handleMouseUp);
   338→
   339→                // Prevent text selection during resize
   340→                document.body.style.userSelect = 'none';
   341→                e.preventDefault();
   342→            }
   343→
   344→            function handleMouseMove(e) {
   345→                if (!isResizing) return;
   346→
   347→                const deltaY = e.clientY - startY;
   348→                const newHeight = Math.max(150, Math.min(window.innerHeight * 0.8, startHeight + deltaY));
   349→
   350→                container.style.height = newHeight + 'px';
   351→
   352→                // Trigger timeline redraw if needed
   353→                if (timeline) {
   354→                    timeline.redraw();
   355→                }
   356→            }
   357→
   358→            function handleMouseUp() {
   359→                isResizing = false;
   360→                document.removeEventListener('mousemove', handleMouseMove);
   361→                document.removeEventListener('mouseup', handleMouseUp);
   362→                document.body.style.userSelect = '';
   363→            }
   364→
   365→            // Add mouse event listeners
   366→            resizeHandle.addEventListener('mousedown', handleMouseDown);
   367→
   368→            // Also allow resizing by dragging the container bottom edge
   369→            container.addEventListener('mousedown', function (e) {
   370→                const rect = container.getBoundingClientRect();
   371→                if (e.clientY >= rect.bottom - 8) {
   372→                    handleMouseDown(e);
   373→                }
   374→            });
   375→        }
   376→
   377→        // Export functions to global scope
   378→        window.toggleTimeline = toggleTimeline;
   379→        window.applyTimelineFilters = applyFilters;
   380→        window.updateTimelinePosition = updateTimelinePosition;
   381→
   382→        // Hook into existing systems
   383→        document.addEventListener('DOMContentLoaded', function () {
   384→            // Listen for filter changes
   385→            const filterToggles = document.querySelectorAll('.filter-toggle');
   386→            filterToggles.forEach(toggle => {
   387→                toggle.addEventListener('click', function () {
   388→                    setTimeout(applyFilters, 50);
   389→                });
   390→            });
   391→
   392→            // Listen for select all/none buttons
   393→            const selectAllButton = document.getElementById('selectAll');
   394→            const selectNoneButton = document.getElementById('selectNone');
   395→            if (selectAllButton) {
   396→                selectAllButton.addEventListener('click', function () {
   397→                    setTimeout(applyFilters, 50);
   398→                });
   399→            }
   400→            if (selectNoneButton) {
   401→                selectNoneButton.addEventListener('click', function () {
   402→                    setTimeout(applyFilters, 50);
   403→                });
   404→            }
   405→
   406→            // Listen for filter toolbar visibility changes
   407→            const filterButton = document.getElementById('filterMessages');
   408→            const closeFiltersButton = document.getElementById('closeFilters');
   409→
   410→            if (filterButton) {
   411→                filterButton.addEventListener('click', function () {
   412→                    setTimeout(updateTimelinePosition, 50);
   413→                });
   414→            }
   415→
   416→            if (closeFiltersButton) {
   417→                closeFiltersButton.addEventListener('click', function () {
   418→                    setTimeout(updateTimelinePosition, 50);
   419→                });
   420→            }
   421→
   422→            // Update timeline position on window resize
   423→            window.addEventListener('resize', updateTimelinePosition);
   424→        });
   425→    })();
   426→</script>

