// Load vis-timeline library dynamically
function loadVisTimeline() {
    return new Promise((resolve, reject) => {
        // Check for different ways vis-timeline might be available
        if ((window.vis && window.vis.Timeline) || 
            (window.Timeline) || 
            (window.VisTimeline && window.VisTimeline.Timeline)) {
            resolve();
            return;
        }

        console.log('Loading vis-timeline from CDN...');

        // Load CSS first
        const link = document.createElement('link');
        link.rel = 'stylesheet';
        link.href = 'https://unpkg.com/vis-timeline/styles/vis-timeline-graph2d.min.css';
        document.head.appendChild(link);

        // Load JavaScript
        const script = document.createElement('script');
        script.src = 'https://unpkg.com/vis-timeline/standalone/umd/vis-timeline-graph2d.min.js';
        script.onload = () => {
            console.log('vis-timeline loaded successfully');
            // Debug: log what's actually available
            console.log('Available globals:', {
                vis: typeof window.vis,
                Timeline: typeof window.Timeline,
                VisTimeline: typeof window.VisTimeline
            });
            if (window.vis) {
                console.log('vis object contents:', Object.keys(window.vis));
            }
            isTimelineLoaded = true;
            resolve();
        };
        script.onerror = () => {
            console.error('Failed to load vis-timeline');
            reject(new Error('Failed to load vis-timeline'));
        };
        document.head.appendChild(script);
    });
}

