   434→                document.removeEventListener('mousemove', handleMouseMove);
   435→                document.removeEventListener('mouseup', handleMouseUp);
   436→                document.body.style.userSelect = '';
   437→            }
   438→
   439→            // Add mouse event listeners
   440→            resizeHandle.addEventListener('mousedown', handleMouseDown);
   441→
   442→            // Also allow resizing by dragging the container bottom edge
   443→            container.addEventListener('mousedown', function (e) {
   444→                const rect = container.getBoundingClientRect();
   445→                if (e.clientY >= rect.bottom - 8) {
   446→                    handleMouseDown(e);
   447→                }
   448→            });
   449→        }
   450→
   451→        // Export functions to global scope
   452→        window.toggleTimeline = toggleTimeline;
   453→        window.applyTimelineFilters = applyFilters;
   454→        window.updateTimelinePosition = updateTimelinePosition;
   455→
   456→        // Hook into existing systems
   457→        document.addEventListener('DOMContentLoaded', function () {
   458→            // Listen for filter changes
   459→            const filterToggles = document.querySelectorAll('.filter-toggle');
   460→            filterToggles.forEach(toggle => {
   461→                toggle.addEventListener('click', function () {
   462→                    setTimeout(applyFilters, 50);
   463→                });
   464→            });
   465→
   466→            // Listen for select all/none buttons
   467→            const selectAllButton = document.getElementById('selectAll');
   468→            const selectNoneButton = document.getElementById('selectNone');
   469→            if (selectAllButton) {
   470→                selectAllButton.addEventListener('click', function () {
   471→                    setTimeout(applyFilters, 50);
   472→                });
   473→            }
   474→            if (selectNoneButton) {
   475→                selectNoneButton.addEventListener('click', function () {
   476→                    setTimeout(applyFilters, 50);
   477→                });
   478→            }
   479→
   480→            // Listen for filter toolbar visibility changes
   481→            const filterButton = document.getElementById('filterMessages');
   482→            const closeFiltersButton = document.getElementById('closeFilters');
   483→
   484→            if (filterButton) {
   485→                filterButton.addEventListener('click', function () {
   486→                    setTimeout(updateTimelinePosition, 50);
   487→                });
   488→            }
   489→
   490→            if (closeFiltersButton) {
   491→                closeFiltersButton.addEventListener('click', function () {
   492→                    setTimeout(updateTimelinePosition, 50);
   493→                });
   494→            }
   495→
   496→            // Update timeline position on window resize
