     1→<!-- Timeline Component Template -->
     2→<!-- vis-timeline integration for transcript visualization -->
     3→
     4→<div id="timeline-container"
     5→    style="display: none; position: sticky; top: 0; z-index: 100; background: white; border-bottom: 1px solid #ddd; width: 100vw; margin-left: calc(-50vw + 50%); overflow: hidden; min-height: 150px; max-height: 80vh;">
     6→    <div id="timeline-visualization" style="height: calc(100% - 8px); width: 100%;"></div>
     7→    <div id="timeline-resize-handle"
     8→        style="position: absolute; bottom: 0; left: 0; right: 0; height: 8px; background: linear-gradient(to bottom, transparent, #ddd); cursor: ns-resize; display: flex; align-items: center; justify-content: center;">
     9→        <div style="width: 40px; height: 3px; background: #999; border-radius: 2px;"></div>
    10→    </div>
    11→</div>
    12→
    13→<script id="timeline-script">
    14→    // Timeline functionality - inline for self-contained HTML
    15→    (function () {
    16→        let timeline = null;
    17→        let items = null;
    18→        let groups = null;
    19→        let isTimelineLoaded = false;
    20→        let timelineIdToElement = new Map(); // Map timeline IDs to DOM elements
    21→        let isResizing = false;
    22→
    23→        // Message type to group mapping
    24→        const messageTypeGroups = {
    25→            'user': { id: 'user', content: '🤷 User', style: 'background-color: #e3f2fd;' },
    26→            'assistant': { id: 'assistant', content: '🤖 Assistant', style: 'background-color: #f3e5f5;' },
    27→            'tool_use': { id: 'tool_use', content: '🛠️ Tool Use', style: 'background-color: #fff3e0;' },
    28→            'tool_result': { id: 'tool_result', content: '🧰 Tool Result', style: 'background-color: #e8f5e8;' },
    29→            'thinking': { id: 'thinking', content: '💭 Thinking', style: 'background-color: #fce4ec;' },
    30→            'system': { id: 'system', content: '⚙️ System', style: 'background-color: #f5f5f5;' },
    31→            'image': { id: 'image', content: '🖼️ Image', style: 'background-color: #e1f5fe;' },
    32→            'sidechain': { id: 'sidechain', content: '🔗 Sub-assistant', style: 'background-color: #e8f5e8;' }
    33→        };
    34→
    35→        // Build timeline data from messages
    36→        function buildTimelineData() {
    37→            const timelineItems = [];
    38→            const timelineGroups = [];
    39→            const usedGroups = new Set();
    40→
    41→            // Clear existing mapping
    42→            timelineIdToElement.clear();
    43→
    44→            // Get all messages from the page
    45→            const messages = document.querySelectorAll('.message:not(.session-header)');
    46→
    47→            messages.forEach((messageEl, index) => {
    48→                // Extract message data - handle both simple and complex CSS classes
    49→                const classList = Array.from(messageEl.classList);
    50→                let messageType = 'system'; // Default fallback
    51→                
    52→                // Check for sidechain first (sub-assistant messages)
    53→                if (classList.includes('sidechain')) {
    54→                    messageType = 'sidechain';
    55→                } else if (classList.includes('system-warning') || classList.includes('system-error') || classList.includes('system-info')) {
    56→                    messageType = 'system';
    57→                } else {
    58→                    // Look for standard message types
    59→                    messageType = classList.find(cls =>
    60→                        ['user', 'assistant', 'tool_use', 'tool_result', 'thinking', 'system', 'image'].includes(cls)
    61→                    ) || 'system';
    62→                }
    63→
    64→                const timestampEl = messageEl.querySelector('.timestamp');
    65→                if (!timestampEl) return; // Skip if no timestamp
    66→                const timestamp = timestampEl.textContent.trim();
    67→
    68→                // Get message content preview
    69→                const contentEl = messageEl.querySelector('.content');
    70→                let content = '';
    71→                if (contentEl) {
    72→                    let textContent = contentEl.textContent || contentEl.innerText || '';
    73→                    
    74→                    // For system messages, try to extract just the message without the prefix
    75→                    if (messageType === 'system') {
    76→                        // System messages often have format like "⚠️ System Warning: message content"
    77→                        const systemMatch = textContent.match(/^[⚠️❌ℹ️]?\s*System\s+\w+:\s*(.+)$/);
    78→                        if (systemMatch) {
    79→                            textContent = systemMatch[1];
    80→                        }
    81→                    }
    82→                    
    83→                    content = textContent.length > 100 ? textContent.substring(0, 100) + '...' : textContent;
    84→                }
    85→
    86→                // For tool_use messages, try to extract the tool name
    87→                if (messageType === 'tool_use') {
    88→                    // Try to extract tool name from JSON content
    89→                    const nameMatch = content.match(/"name":\s*"([^"]+)"/);
    90→                    if (nameMatch) {
    91→                        const toolName = nameMatch[1];
    92→                        content = toolName + ': ' + content.replace(/"name":\s*"[^"]+",?\s*/, '');
    93→                    } else {
    94→                        // Fallback: try to extract from header if available
    95→                        const headerEl = messageEl.querySelector('.header span');
    96→                        if (headerEl) {
    97→                            const headerText = headerEl.textContent || '';
    98→                            const toolMatch = headerText.match(/🛠️\s*(.+) \(Id:.*/);
    99→                            if (toolMatch) {
   100→                                content = toolMatch[1].replace("Tool Use: ", "") + (content ? ': ' + content : '');
   101→                            }
   102→                        }
   103→                    }
   104→                }
   105→
   106→                // Add group if not already added
   107→                if (!usedGroups.has(messageType)) {
   108→                    timelineGroups.push(messageTypeGroups[messageType]);
   109→                    usedGroups.add(messageType);
   110→                }
   111→
   112→                // Store mapping for click handling
   113→                timelineIdToElement.set(index, messageEl);
   114→
   115→                // Strip content to make tooltip formatting more uniform
   116→                // TODO: this is very basic and TodoWrites have weird spacing so will need some more work
   117→                let title = contentEl.innerHTML.includes("<pre") ? contentEl.innerHTML : `<pre>${contentEl.innerHTML}</pre>`
   118→                if (title.includes("<details")) {
   119→                    title = title.replace(/(<summary>.*<\/summary>)/gs, '').replace(/<details class="collapsible-details">(.*?)<\/details>/gs, (m, p) => p)
   120→                }
   121→                title = title.replace(/<pre>[\s\r\n]+(.*?)[\s\r\n]+<\/pre>/gs, (m, p) => `<pre>${p}</pre>`)
   122→
   123→                // Adjust content display based on message type
   124→                let displayContent = content || messageTypeGroups[messageType].content;
   125→                if (messageType === 'sidechain') {
   126→                    // For sidechain messages, prefix with appropriate icon based on original type
   127→                    if (classList.includes('user')) {
   128→                        displayContent = '📝 ' + (content || 'Sub-assistant prompt');
   129→                    } else if (classList.includes('assistant')) {
   130→                        displayContent = '🔗 ' + (content || 'Sub-assistant response');
   131→                    }
   132→                }
   133→
   134→                // Create timeline item
   135→                timelineItems.push({
   136→                    id: index,
   137→                    content: displayContent,
   138→                    start: timestamp,
   139→                    group: messageType,
   140→                    tooltip: {
   141→                        // FIXME: This followMouse doesn't work for some reason and the tooltip box gets cut off for the bottom timeline boxes
   142→                        followMouse: true,
   143→                        overflowMethod: 'cap'
   144→                    },
   145→                    title,
   146→                    className: `timeline-item-${messageType}`
   147→                });
   148→            });
   149→
   150→            return { items: timelineItems, groups: timelineGroups };
   151→        }
   152→
   153→        // Filter timeline items based on current message filters
   154→        function applyFilters() {
   155→            if (!timeline || !items) return;
   156→
   157→            // Get active filter types
   158→            const filterToggles = document.querySelectorAll('.filter-toggle');
   159→            const activeTypes = [];
   160→            let hasActiveFilters = false;
   161→
   162→            filterToggles.forEach(toggle => {
   163→                if (toggle.classList.contains('active')) {
   164→                    activeTypes.push(toggle.dataset.type);
   165→                    hasActiveFilters = true;
   166→                }
   167→            });
   168→
   169→            // If no filters are active, show all items
   170→            if (!hasActiveFilters) {
   171→                timeline.setItems(items);
   172→                return;
   173→            }
   174→
   175→            // Filter items based on active types
   176→            const filteredItems = items.get().filter(item => {
   177→                return activeTypes.includes(item.group);
   178→            });
   179→
   180→            timeline.setItems(new vis.DataSet(filteredItems));
   181→        }
   182→
   183→        // Handle timeline item click - scroll to corresponding message
   184→        function onTimelineSelect(event) {
   185→            const selection = timeline.getSelection();
   186→            if (selection.length > 0) {
   187→                const itemId = selection[0];
   188→                const messageEl = timelineIdToElement.get(itemId);
   189→                if (messageEl) {
   190→                    // Calculate timeline height for proper scroll positioning
   191→                    const timelineContainer = document.getElementById('timeline-container');
   192→                    const timelineHeight = timelineContainer ? timelineContainer.offsetHeight : 0;
   193→
   194→                    // Scroll so message top aligns with timeline bottom
   195→                    const elementTop = messageEl.offsetTop;
   196→                    const scrollPosition = elementTop - timelineHeight - 10; // 10px padding
   197→
   198→                    window.scrollTo({
   199→                        top: Math.max(0, scrollPosition),
   200→                        behavior: 'smooth'
   201→                    });
   202→
   203→                    // Highlight the message briefly
   204→                    messageEl.style.backgroundColor = '#fff3cd';
   205→                    setTimeout(() => {
   206→                        messageEl.style.backgroundColor = '';
   207→                    }, 2000);
   208→                }
   209→            }
   210→        }
   211→
   212→        // Initialize timeline
   213→        function initTimeline() {
   214→            if (timeline) return; // Already initialized
   215→
   216→            console.log('Initializing vis-timeline...');
   217→
   218→            const container = document.getElementById('timeline-visualization');
   219→            if (!container) {
   220→                console.error('Timeline container not found');
   221→                return;
   222→            }
   223→
   224→            // Build timeline data
   225→            const timelineData = buildTimelineData();
   226→            if (timelineData.items.length === 0) {
   227→                console.warn('No timeline items found');
   228→                return;
   229→            }
   230→
   231→            // Create DataSets - handle different ways DataSet might be exposed
   232→            let DataSetClass;
   233→            if (window.vis && window.vis.DataSet) {
   234→                DataSetClass = window.vis.DataSet;
   235→            } else if (window.DataSet) {
   236→                DataSetClass = window.DataSet;
   237→            } else if (window.VisTimeline && window.VisTimeline.DataSet) {
   238→                DataSetClass = window.VisTimeline.DataSet;
   239→            } else {
   240→                console.error('DataSet class not found, using plain arrays');
   241→                items = timelineData.items;
   242→                groups = timelineData.groups;
   243→            }
   244→
   245→            if (DataSetClass) {
   246→                console.log('Using DataSet class:', DataSetClass);
   247→                items = new DataSetClass(timelineData.items);
   248→                groups = new DataSetClass(timelineData.groups);
   249→            }
   250→
   251→            // Timeline options
   252→            const options = {
   253→                height: '100%',
   254→                stack: true,
   255→                showCurrentTime: true,
   256→                zoomMin: 1000 * 1, // 1 second
   257→                zoomMax: 1000 * 60 * 60 * 24 * 30, // 30 days
   258→                orientation: 'top',
   259→                align: 'left',
   260→                margin: {
   261→                    item: 2,
   262→                    axis: 2
   263→                },
   264→                groupOrder: (a, b) => {
   265→                    const order = ['user', 'assistant', 'sidechain', 'tool_use', 'tool_result', 'thinking', 'system', 'image'];
   266→                    return order.indexOf(a.id) - order.indexOf(b.id);
   267→                }
   268→            };
   269→
   270→            // Create timeline - handle different ways Timeline might be exposed
   271→            let TimelineClass;
   272→            if (window.vis && window.vis.Timeline) {
   273→                TimelineClass = window.vis.Timeline;
   274→            } else if (window.Timeline) {
   275→                TimelineClass = window.Timeline;
   276→            } else if (window.VisTimeline && window.VisTimeline.Timeline) {
   277→                TimelineClass = window.VisTimeline.Timeline;
   278→            } else {
   279→                console.error('Timeline class not found in any expected location');
   280→                return;
   281→            }
   282→
   283→            console.log('Using Timeline class:', TimelineClass);
   284→            timeline = new TimelineClass(container, items, groups, options);
   285→
   286→            // Add event listeners
   287→            timeline.on('select', onTimelineSelect);
   288→
   289→            // Apply current filters
   290→            applyFilters();
   291→
   292→            console.log('Timeline initialized with', timelineData.items.length, 'items and', timelineData.groups.length, 'groups');
   293→        }
   294→
   295→        // Load vis-timeline library dynamically
   296→        function loadVisTimeline() {
   297→            return new Promise((resolve, reject) => {
   298→                // Check for different ways vis-timeline might be available
   299→                if ((window.vis && window.vis.Timeline) || 
   300→                    (window.Timeline) || 
   301→                    (window.VisTimeline && window.VisTimeline.Timeline)) {
   302→                    resolve();
   303→                    return;
   304→                }
   305→
   306→                console.log('Loading vis-timeline from CDN...');
   307→
   308→                // Load CSS first
   309→                const link = document.createElement('link');
   310→                link.rel = 'stylesheet';
   311→                link.href = 'https://unpkg.com/vis-timeline/styles/vis-timeline-graph2d.min.css';
   312→                document.head.appendChild(link);
   313→
   314→                // Load JavaScript
   315→                const script = document.createElement('script');
   316→                script.src = 'https://unpkg.com/vis-timeline/standalone/umd/vis-timeline-graph2d.min.js';
   317→                script.onload = () => {
   318→                    console.log('vis-timeline loaded successfully');
   319→                    // Debug: log what's actually available
   320→                    console.log('Available globals:', {
   321→                        vis: typeof window.vis,
   322→                        Timeline: typeof window.Timeline,
   323→                        VisTimeline: typeof window.VisTimeline
   324→                    });
   325→                    if (window.vis) {
   326→                        console.log('vis object contents:', Object.keys(window.vis));
   327→                    }
