   379→        // Update timeline position when filter bar is toggled
   380→        function updateTimelinePosition() {
   381→            const container = document.getElementById('timeline-container');
   382→            const filterToolbar = document.querySelector('.filter-toolbar');
   383→
   384→            if (container && filterToolbar) {
   385→                const filterHeight = filterToolbar.offsetHeight;
   386→                const computedStyle = getComputedStyle(filterToolbar);
   387→                const isFilterVisible = computedStyle.display !== 'none' &&
   388→                    computedStyle.visibility !== 'hidden' &&
   389→                    filterHeight > 0;
   390→
   391→                container.style.top = isFilterVisible ? `${filterHeight}px` : '0px';
   392→            }
   393→        }
