   417→
   418→            function handleMouseMove(e) {
   419→                if (!isResizing) return;
   420→
   421→                const deltaY = e.clientY - startY;
   422→                const newHeight = Math.max(150, Math.min(window.innerHeight * 0.8, startHeight + deltaY));
