   488→            }
   489→
   490→            if (closeFiltersButton) {
   491→                closeFiltersButton.addEventListener('click', function () {
   492→                    setTimeout(updateTimelinePosition, 50);
   493→                });
   494→            }
   495→
   496→            // Update timeline position on window resize
