     1→<!-- Timeline Component Template -->
     2→<!-- vis-timeline integration for transcript visualization -->
     3→
     4→<div id="timeline-container"
     5→    style="display: none; position: sticky; top: 0; z-index: 100; background: white; border-bottom: 1px solid #ddd; width: 100vw; margin-left: calc(-50vw + 50%); overflow: hidden; min-height: 150px; max-height: 80vh;">
     6→    <div id="timeline-visualization" style="height: calc(100% - 8px); width: 100%;"></div>
     7→    <div id="timeline-resize-handle"
     8→        style="position: absolute; bottom: 0; left: 0; right: 0; height: 8px; background: linear-gradient(to bottom, transparent, #ddd); cursor: ns-resize; display: flex; align-items: center; justify-content: center;">
     9→        <div style="width: 40px; height: 3px; background: #999; border-radius: 2px;"></div>
    10→    </div>
