   182→
   183→        // Handle timeline item click - scroll to corresponding message
   184→        function onTimelineSelect(event) {
   185→            const selection = timeline.getSelection();
   186→            if (selection.length > 0) {
   187→                const itemId = selection[0];
   188→                const messageEl = timelineIdToElement.get(itemId);
   189→                if (messageEl) {
   190→                    // Calculate timeline height for proper scroll positioning
   191→                    const timelineContainer = document.getElementById('timeline-container');
