   399→
   400→            if (!container || !resizeHandle) return;
   401→
   402→            let startY = 0;
   403→            let startHeight = 0;
   404→
   405→            function handleMouseDown(e) {
   406→                isResizing = true;
   407→                startY = e.clientY;
   408→                startHeight = container.offsetHeight;
   409→
   410→                document.addEventListener('mousemove', handleMouseMove);
   411→                document.addEventListener('mouseup', handleMouseUp);
   412→
   413→                // Prevent text selection during resize
   414→                document.body.style.userSelect = 'none';
   415→                e.preventDefault();
   416→            }
   417→
   418→            function handleMouseMove(e) {
   419→                if (!isResizing) return;
   420→
   421→                const deltaY = e.clientY - startY;
   422→                const newHeight = Math.max(150, Math.min(window.innerHeight * 0.8, startHeight + deltaY));
