     1→<!DOCTYPE html>
     2→<html lang='en'>
     3→
     4→<head>
     5→    <meta charset='UTF-8'>
     6→    <meta name='viewport' content='width=device-width, initial-scale=1.0'>
     7→    <title>{{ title }}</title>
     8→    {% from 'components/session_nav.html' import render_session_nav %}
     9→    <style>
    10→{% include 'components/global_styles.css' %}
    11→{% include 'components/message_styles.css' %}
    12→{% include 'components/session_nav_styles.css' %}
    13→{% include 'components/filter_styles.css' %}
    14→{% include 'components/todo_styles.css' %}
    15→{% include 'components/timeline_styles.css' %}
    16→    </style>
    17→</head>
    18→
    19→<body>
    20→    <h1 id="title">{{ title }}</h1>
    21→
    22→    <!-- Timeline Component -->
    23→    {% include 'components/timeline.html' %}
    24→
    25→    <!-- Filter Toolbar -->
    26→    <div class="filter-toolbar">
    27→        <div class="filter-label">
    28→            <h3>Filter:</h3>
    29→        </div>
    30→        <div class="filter-toggles">
    31→            <button class="filter-toggle active" data-type="user">🤷 User <span class="count">(0)</span></button>
    32→            <button class="filter-toggle active" data-type="assistant">🤖 Assistant <span
    33→                    class="count">(0)</span></button>
    34→            <button class="filter-toggle active" data-type="system">⚙️ System <span class="count">(0)</span></button>
    35→            <button class="filter-toggle active" data-type="tool_use">🛠️ Tool Use <span
    36→                    class="count">(0)</span></button>
    37→            <button class="filter-toggle active" data-type="tool_result">🧰 Tool Results <span
    38→                    class="count">(0)</span></button>
    39→            <button class="filter-toggle active" data-type="thinking">💭 Thinking <span
    40→                    class="count">(0)</span></button>
    41→            <button class="filter-toggle active" data-type="image">🖼️ Images <span class="count">(0)</span></button>
    42→        </div>
    43→        <div class="filter-actions">
    44→            <button class="filter-action-btn" id="selectAll">All</button>
    45→            <button class="filter-action-btn" id="selectNone">None</button>
    46→            <button class="filter-action-btn" id="closeFilters" title="Close filters">✕</button>
    47→        </div>
    48→    </div>
    49→
    50→    {% if sessions and sessions|length > 1 %}
    51→    {{ render_session_nav(sessions, "toc") }}
    52→    {% endif %}
    53→
    54→    {% for message in messages %}
    55→    {% if message.is_session_header %}
    56→    <div class="session-divider"></div>
    57→    <div id='session-{{ message.session_id }}' class='message session-header'>
    58→        <div class='header'>Session: {{ message.content_html }}</div>
    59→        {% if message.session_subtitle %}
    60→        <div class='session-subtitle' style='font-size: 0.9em; color: #666; margin-top: 4px;'>{{
    61→            message.session_subtitle }} ({{message.session_subtitle.session_id}})</div>
    62→        {% endif %}
    63→
    64→    </div>
    65→    {% else %}
    66→    <div class='message {{ message.css_class }}'>
    67→        <div class='header'>
    68→            <span>{% if message.css_class == 'user' %}🤷 {% elif message.css_class == 'assistant' %}🤖 {% elif
    69→                message.css_class == 'system' %}⚙️ {% elif message.css_class == 'tool_use' %}🛠️ {% elif
    70→                message.css_class == 'tool_result' %}🧰 {% elif message.css_class == 'thinking' %}💭 {% elif
    71→                message.css_class == 'image' %}🖼️ {% endif %}{{ message.display_type }}</span>
    72→            <div style='display: flex; flex-direction: column; align-items: flex-end; gap: 2px;'>
    73→                <span class='timestamp'>{{ message.formatted_timestamp }}</span>
    74→                {% if message.token_usage %}
    75→                <span class='token-usage' style='font-size: 0.75em; color: #888;'>{{ message.token_usage }}</span>
    76→                {% endif %}
    77→            </div>
    78→        </div>
    79→        <div class='content'>{{ message.content_html | safe }}</div>
    80→    </div>
    81→    {% endif %}
    82→    {% endfor %}
    83→
    84→    <button class="timeline-toggle floating-btn" id="toggleTimeline" title="Show timeline">📆</button>
    85→    <button class="filter-messages floating-btn" id="filterMessages" title="Toggle filters">🔍</button>
    86→    <button class="toggle-details floating-btn" id="toggleDetails" title="Toggle all details">📋</button>
    87→    <a class="scroll-top floating-btn" title="Scroll to top" href="#title">🔝</a>
    88→
    89→    <script>
    90→        document.addEventListener('DOMContentLoaded', function () {
    91→            const toggleButton = document.getElementById('toggleDetails');
    92→            const timelineButton = document.getElementById('toggleTimeline');
    93→            const filterButton = document.getElementById('filterMessages');
    94→            const filterToolbar = document.querySelector('.filter-toolbar');
    95→            const selectAllButton = document.getElementById('selectAll');
    96→            const selectNoneButton = document.getElementById('selectNone');
    97→            const closeFiltersButton = document.getElementById('closeFilters');
    98→            const filterToggles = document.querySelectorAll('.filter-toggle');
    99→
   100→            // Timeline toggle functionality
   101→            if (timelineButton) {
   102→                timelineButton.addEventListener('click', function () {
   103→                    if (window.toggleTimeline) {
   104→                        window.toggleTimeline();
   105→                    }
   106→                });
   107→            }
   108→
   109→            // Toggle details functionality
   110→            function updateToggleButton() {
   111→                const allDetails = document.querySelectorAll('details.collapsible-details');
   112→                const openCount = document.querySelectorAll('details[open].collapsible-details').length;
   113→                const totalCount = allDetails.length;
   114→
   115→                if (totalCount === 0) {
   116→                    toggleButton.style.display = 'none';
   117→                    return;
   118→                }
   119→
   120→                // If more than half are open, show "close all" state, otherwise show "open all"
   121→                const mostlyOpen = openCount > totalCount / 2;
   122→                toggleButton.textContent = mostlyOpen ? '📦' : '🗃️';
   123→                toggleButton.title = mostlyOpen ? 'Close all details' : 'Open all details';
   124→            }
   125→
   126→            function toggleAllDetails() {
   127→                const allDetails = document.querySelectorAll('details.collapsible-details');
   128→                const openCount = document.querySelectorAll('details[open].collapsible-details').length;
   129→                const shouldOpen = openCount <= allDetails.length / 2;
   130→
   131→                allDetails.forEach(details => {
   132→                    if (shouldOpen) {
   133→                        details.setAttribute('open', '');
   134→                    } else {
   135→                        details.removeAttribute('open');
   136→                    }
   137→                });
   138→
   139→                updateToggleButton();
   140→            }
   141→
   142→            toggleButton.addEventListener('click', toggleAllDetails);
   143→
   144→            // Filter toolbar toggle functionality
   145→            function toggleFilterToolbar() {
   146→                const isVisible = filterToolbar.classList.contains('visible');
   147→                if (isVisible) {
   148→                    filterToolbar.classList.remove('visible');
   149→                    filterButton.classList.remove('active');
   150→                    filterButton.title = 'Show filters';
   151→                } else {
   152→                    filterToolbar.classList.add('visible');
   153→                    filterButton.classList.add('active');
   154→                    filterButton.title = 'Hide filters';
   155→                }
   156→            }
   157→
   158→            filterButton.addEventListener('click', toggleFilterToolbar);
   159→            closeFiltersButton.addEventListener('click', toggleFilterToolbar);
   160→
   161→            // Count messages by type and update button labels
   162→            function updateMessageCounts() {
   163→                const messageTypes = ['user', 'assistant', 'system', 'tool_use', 'tool_result', 'thinking', 'image'];
   164→
   165→                messageTypes.forEach(type => {
   166→                    const messages = document.querySelectorAll(`.message.${type}:not(.session-header)`);
   167→                    const count = messages.length;
   168→                    const toggle = document.querySelector(`[data-type="${type}"]`);
   169→                    const countSpan = toggle.querySelector('.count');
   170→
   171→                    if (countSpan) {
   172→                        countSpan.textContent = `(${count})`;
   173→
   174→                        // Hide toggles for message types with 0 count
   175→                        if (count === 0) {
   176→                            toggle.style.display = 'none';
   177→                        } else {
   178→                            toggle.style.display = 'flex';
   179→                        }
   180→                    }
   181→                });
   182→            }
   183→
   184→            // Filter functionality
   185→            function applyFilter() {
   186→                const activeTypes = Array.from(filterToggles)
   187→                    .filter(toggle => toggle.classList.contains('active'))
   188→                    .map(toggle => toggle.dataset.type);
   189→
   190→                // Show/hide messages based on active toggle buttons
   191→                const allMessages = document.querySelectorAll('.message:not(.session-header)');
   192→                allMessages.forEach(message => {
   193→                    const shouldShow = activeTypes.some(type => message.classList.contains(type));
   194→                    if (shouldShow) {
   195→                        message.classList.remove('filtered-hidden');
   196→                    } else {
   197→                        message.classList.add('filtered-hidden');
   198→                    }
   199→                });
   200→
   201→                // Update visible counts in real-time
   202→                updateVisibleCounts();
   203→
   204→                // Update filter button appearance based on whether all types are selected
   205→                const allTypesSelected = activeTypes.length === filterToggles.length;
   206→                if (!allTypesSelected && filterToolbar.classList.contains('visible')) {
   207→                    filterButton.classList.add('active');
   208→                } else if (allTypesSelected && filterToolbar.classList.contains('visible')) {
   209→                    filterButton.classList.add('active');
   210→                }
   211→            }
   212→
   213→            function updateVisibleCounts() {
   214→                const messageTypes = ['user', 'assistant', 'system', 'tool_use', 'tool_result', 'thinking', 'image'];
   215→
   216→                messageTypes.forEach(type => {
   217→                    const visibleMessages = document.querySelectorAll(`.message.${type}:not(.session-header):not(.filtered-hidden)`);
   218→                    const totalMessages = document.querySelectorAll(`.message.${type}:not(.session-header)`);
   219→                    const visibleCount = visibleMessages.length;
   220→                    const totalCount = totalMessages.length;
   221→
   222→                    const toggle = document.querySelector(`[data-type="${type}"]`);
   223→                    const countSpan = toggle.querySelector('.count');
   224→
   225→                    if (countSpan && totalCount > 0) {
   226→                        // Show "visible/total" format when filtering is active
   227→                        const activeTypes = Array.from(filterToggles)
   228→                            .filter(toggle => toggle.classList.contains('active'))
   229→                            .map(toggle => toggle.dataset.type);
   230→
   231→                        const isFiltering = activeTypes.length < filterToggles.length;
   232→
   233→                        if (isFiltering && visibleCount !== totalCount) {
   234→                            countSpan.textContent = `(${visibleCount}/${totalCount})`;
   235→                        } else {
   236→                            countSpan.textContent = `(${totalCount})`;
   237→                        }
   238→                    }
   239→                });
   240→            }
   241→
   242→            function toggleFilter(button) {
   243→                button.classList.toggle('active');
   244→                applyFilter();
   245→            }
   246→
   247→            function selectAllTypes() {
   248→                filterToggles.forEach(toggle => {
   249→                    toggle.classList.add('active');
   250→                });
   251→                applyFilter();
   252→            }
